import { PHOTOS } from '../../data/photos';
import { cx } from '../../utils/cx';
import styles from './Photo.module.css';

interface PhotoProps {
  /** Key into PHOTOS — see src/data/photos.ts (generated by `npm run photos`). */
  slug: string;
  /** The `sizes` hint for this slot. Getting it right is what keeps phones light. */
  sizes: string;
  /** Extra class from the calling section: the frame, its crop and its reveals. */
  className?: string;
  /** Below-the-fold photos stay lazy; the hero cutout is the only eager image. */
  priority?: boolean;
  /** Overrides the alt text stored with the photo. */
  alt?: string;
  /** Nudges the crop inside the frame, e.g. 'center 30%' for a tall portrait. */
  objectPosition?: string;
}

/**
 * A photograph from the pipeline. Always a <picture>: AVIF first, WebP second,
 * with the intrinsic size on the <img> so the frame never shifts while it loads.
 *
 * Every photo here is licensed placeholder photography until the club sends its
 * own shoot — see IMAGE_CREDITS.md. Swapping one is `npm run photos` and nothing
 * else; no component needs to change.
 */
export function Photo({
  slug,
  sizes,
  className,
  priority = false,
  alt,
  objectPosition,
}: PhotoProps) {
  const photo = PHOTOS[slug];
  if (!photo) {
    // A missing slug is a build-time mistake, not a runtime state: fail loudly in
    // development and render nothing in production rather than a broken frame.
    if (import.meta.env.DEV) throw new Error(`Unknown photo slug: ${slug}`);
    return null;
  }

  return (
    <picture className={cx(styles.picture, className)}>
      <source type="image/avif" srcSet={photo.avif} sizes={sizes} />
      <source type="image/webp" srcSet={photo.webp} sizes={sizes} />
      <img
        className={styles.img}
        src={photo.src}
        alt={alt ?? photo.alt}
        width={photo.width}
        height={photo.height}
        style={objectPosition ? { objectPosition } : undefined}
        loading={priority ? 'eager' : 'lazy'}
        decoding={priority ? 'sync' : 'async'}
        {...(priority ? { fetchPriority: 'high' as const } : {})}
      />
    </picture>
  );
}
